"""Parser matching the behaviour of the compiled ``reader`` binary."""

MAGIC = 0xA8BD8F22
VERSION_TAG = 0xB5
MAX_FILE_SIZE = 65536
MAX_RECORDS = 8


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    size = len(data)
    if size > MAX_FILE_SIZE:
        return None
    if size < 5 + 4:
        return None
    if int.from_bytes(data[0:4], "little") != MAGIC:
        return None
    if data[4] != VERSION_TAG:
        return None

    offset = 5

    def read_uint(width: int):
        nonlocal offset
        if offset > size or width > size - offset:
            return None
        value = int.from_bytes(data[offset:offset + width], "little")
        offset += width
        return value

    record_count = read_uint(4)
    if record_count is None:
        return None
    if record_count > MAX_RECORDS:
        return None

    stock = read_uint(2)
    if stock is None:
        return None
    version = read_uint(1)
    if version is None:
        return None

    records = []
    for _ in range(record_count):
        timestamp = read_uint(4)
        if timestamp is None:
            return None
        length = read_uint(4)
        if length is None:
            return None
        enabled = read_uint(1)
        if enabled is None:
            return None
        records.append({
            "enabled": enabled,
            "length": length,
            "timestamp": timestamp,
        })

    if offset != size:
        return None

    return {
        "header": {"stock": stock, "version": version},
        "records": records,
    }
